import urllib.request,urllib.error,json,sys,uuid
base='http://127.0.0.1:8787'; results=[]; prefix='test-'+uuid.uuid4().hex[:8]+'-'
def req(path,method='GET',data=None,identity=None):
 h={'Content-Type':'application/json'}
 if identity:h.update({'oai-authenticated-user-id':prefix+identity,'oai-authenticated-user-email':prefix+identity+'@test.invalid'})
 request=urllib.request.Request(base+path,data=json.dumps(data).encode() if data is not None else None,headers=h,method=method)
 try:
  r=urllib.request.urlopen(request);return r.status,json.load(r)
 except urllib.error.HTTPError as e:return e.code,json.load(e)
def check(name, condition):
 results.append({'test':name,'passed':bool(condition)});print(('PASS ' if condition else 'FAIL ')+name)
