req('/api/interests','POST',{'targetId':'demo-mika','intention':'friend'},'local-a');req('/api/interests','POST',{'targetId':'demo-mika','intention':'friend'},'local-a');ints=req('/api/interests',identity='local-a')[1]['interests'];check('interest idempotency',len(ints)==1);iid=ints[0]['id'];check('pending does not imply mutual',ints[0]['state']=='pending' and not ints[0]['targetApproved']);check('other identity cannot approve demo',req('/api/interests/'+iid,'PATCH',{'action':'simulate'},'local-b')[0]==404);req('/api/interests/'+iid,'PATCH',{'action':'simulate'},'local-a');i=req('/api/interests',identity='local-a')[1]['interests'][0];check('second approval explicitly simulated',i['state']=='mutual' and i['simulated']);req('/api/interests/'+iid,'PATCH',{'action':'withdraw'},'local-a');check('withdraw clears both approvals',all(not req('/api/interests',identity='local-a')[1]['interests'][0][f] for f in ['initiatorApproved','targetApproved']));
