status,pub=req('/api/profiles/'+bid,identity='live-a');check('public projection excludes hidden evidence and gender',status==200 and pub['profile']['gender']=='' and all(e['id']!='hidden' for e in pub['profile']['evidence']));req('/api/interests','POST',{'targetId':bid,'intention':'friend'},'live-a');ii=req('/api/interests',identity='live-a')[1]['interests'][0]['id'];check('initiator cannot approve other side',req('/api/interests/'+ii,'PATCH',{'action':'accept'},'live-a')[0]==403);check('recipient independently approves',req('/api/interests/'+ii,'PATCH',{'action':'accept'},'live-b')[0]==200);check('mutual state uses two approvals',req('/api/interests',identity='live-a')[1]['interests'][0]['state']=='mutual');check('recipient can withdraw',req('/api/interests/'+ii,'PATCH',{'action':'withdraw'},'live-b')[0]==200)
